import{_ as t,W as i,s as r,u as d,I as a,ah as o,w as s,Z as l,A as p}from"./chunks/framework.B4JzB-Td.js";import"./chunks/theme.Xs8fIzCW.js";const k=JSON.parse('{"title":"关于编译代码你应该知道的 | LCTT x X-CMD","titleTemplate":false,"description":"关于编译代码你应该知道的 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"关于编译代码你应该知道的 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"关于编译代码你应该知道的 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20221013 What you need to know about compiling code","title":"关于编译代码你应该知道的","tag":"202211"},"relativePath":"202211/20221013 What you need to know about compiling code.md","filePath":"[post].md"}'),u={name:"202211/20221013 What you need to know about compiling code.md"};function m(g,n,b,C,f,c){const e=i("Link");return d(),r("div",null,[n[29]||(n[29]=a("h1",{id:"关于编译代码你应该知道的",tabindex:"-1"},[s("关于编译代码你应该知道的 "),a("a",{class:"header-anchor",href:"#关于编译代码你应该知道的","aria-label":"Permalink to 关于编译代码你应该知道的"},"​")],-1)),n[30]||(n[30]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202211/04/054126nec50keexencosc4.jpg",alt:""})],-1)),n[31]||(n[31]=a("blockquote",null,[a("p",null,"用这个方便的捕鼠器比喻来理解编译代码。")],-1)),a("p",null,[n[1]||(n[1]=s("源代码必须要经过编译才能够运行程序，而对于开源软件，每个人都可以获取源代码。无论你是自己编写了代码，想要编译和运行它，还是下载了某人的项目来尝试它，了解如何通过 ")),l(e,{href:"https://opensource.com/article/19/5/primer-assemblers-compilers-interpreters"},{default:p(()=>n[0]||(n[0]=[s("编译器")])),_:1}),n[2]||(n[2]=s(" 处理源代码，以及编译器如何处理这些代码，这都很有用。"))]),n[32]||(n[32]=o(`<h3 id="创建一个更好的捕鼠器" tabindex="-1">创建一个更好的捕鼠器 <a class="header-anchor" href="#创建一个更好的捕鼠器" aria-label="Permalink to 创建一个更好的捕鼠器">​</a></h3><p>一般情况我们不会将一个捕鼠器比作电脑，但不管你信不信，它确实与你正在使用的设备（手机或电脑）的 CPU 有一些相似之处。经典的捕鼠器（我说的不是 🐈）有两种状态：打开或者释放。你可以认为 <em>打开</em> 是将捕鼠器设置好准备捕获老鼠，以及 <em>释放</em> 是捕鼠器被老鼠触发。某种意义上来说，捕鼠器就像是一台有鼠标的电脑。你可以想象一下这个代码，用一种虚构的语言来描述这个过程：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if mousetrap == 0 then</span></span>
<span class="line"><span>  There&#39;s a mouse!</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>  There&#39;s no mouse yet.</span></span>
<span class="line"><span>end</span></span></code></pre></div><p>换句话说，你可以基于捕鼠器的状态发现是否有老鼠（数据）。当然，捕鼠器不是万无一失的，有可能有一只老鼠在捕鼠器旁边，由于老鼠还没有触发捕鼠器，所以它的状态还是 <em>打开</em> 的。因此该程序可以进行改进，这都是非常典型的。</p><h3 id="开关" tabindex="-1">开关 <a class="header-anchor" href="#开关" aria-label="Permalink to 开关">​</a></h3><p>总的来说，捕鼠器就是一个开关。你会在家里使用开关打开灯。可以从开关中获得许多信息。比如，人们会从你家灯的状态了解到你是否在家。</p><p>你可以根据邻居家灯的状态来改变行为。如果邻居家所有的灯都熄灭了，那么请关掉你大声的音乐，因为人们可能已经上床睡觉了。</p><p>CPU 也使用这样的逻辑，只不过乘以几个数量级，缩小到了微观级别。当 CPU 在特定寄存器上接收到电信号时，可以触发其他一些寄存器，然后触发另一个，以此类推。如果这些寄存器有特定的意义，那么就可以通信。也许激活同一主板上某处的芯片，或者使 LED 亮起，或者改变屏幕上的像素颜色。</p><p>种瓜得瓜，种豆得豆。如果你真的想在多个位置而不是仅限于一处发现老鼠，但是你只有一个捕鼠器，那你应该开发一个应用才行。使用网络摄像头和一些基本的图像识别软件，你可以建立空厨房的模型，然后扫描变化。当老鼠进入厨房，在原先没有老鼠的图像上会有像素的变化。记录下这些数据，如果有无人机可以追踪老鼠并捕获会更好，这样就可以将老鼠赶出厨房了。这时，你通过打开和关闭信号的魔法，创造了一个更好的捕鼠器。</p><h3 id="编译器" tabindex="-1">编译器 <a class="header-anchor" href="#编译器" aria-label="Permalink to 编译器">​</a></h3><p>代码编译器将人们可阅读的代码转换成 CPU 可以理解的机器语言。这是非常复杂的过程，因为 CPU 非常复杂（甚至比捕鼠器更加复杂），同时因为该过程比严格“需要”的更加灵活。并不是所有的编译器都很灵活。有一些编译器只有一个目标，它们只会处理特定格式的代码文件，处理过程也因此而简单明了。</p>`,11)),a("p",null,[n[4]||(n[4]=s("幸运的是，现代的通用编译器并不简单。它们允许你编写不同语言的代码，也允许你用不同的方式链接库文件，并且可以生成运行在不同架构上的文件。")),l(e,{href:"https://opensource.com/article/22/5/gnu-c-compiler"},{default:p(()=>n[3]||(n[3]=[s("GNU 编译器集合")])),_:1}),n[5]||(n[5]=s("（GCC）的 ")),n[6]||(n[6]=a("code",null,"gcc",-1)),n[7]||(n[7]=s(" 编译器 ")),n[8]||(n[8]=a("code",null,"--help",-1)),n[9]||(n[9]=s(" 会输出超过 50 行的选项，LLVM 的 ")),n[10]||(n[10]=a("code",null,"clang",-1)),n[11]||(n[11]=s(" 编译器的 ")),n[12]||(n[12]=a("code",null,"--help",-1)),n[13]||(n[13]=s(" 输出超过 1000 行。GCC 指导手册的字数超过 10 万。"))]),n[33]||(n[33]=o(`<p>当你在编译代码时会有很多选项。</p><p>当然，大多数人并不需要知道所有的选项。我从未读过 GCC 的手册页，因为它们是针对 Objective-C、Fortran 以及我从未听说过的芯片架构的。不过我重视它将代码编译为不同的架构 —— 64 位或者 32 位 —— 的能力，以及在其他行业已经落后的计算机上运行开源软件的能力。</p><h3 id="编译生命周期" tabindex="-1">编译生命周期 <a class="header-anchor" href="#编译生命周期" aria-label="Permalink to 编译生命周期">​</a></h3><p>同样重要的是，理解编译代码的不同阶段。这是一个简单的 C 语言程序的生命周期：</p><ol><li>带有宏定义的 C 源代码 <code>.c</code> 文件，用 <code>cpp</code> 预处理为 <code>.i</code> 文件。</li><li>扩展了宏定义的 C 源代码 <code>.i</code> 文件，会被 <code>gcc</code> 转译成 <code>.s</code> 文件。</li><li>以汇编语言写的文本文件 <code>.s</code> 文件被汇编为目标 <code>.o</code> 文件。</li><li>带有 CPU 指令的二进制目标代码，以及其他目标文件和库 <code>*.o</code> 文件，以内存区域无关的偏移量，使用 <code>ld</code> 链接以生成可执行文件。</li><li>最终的二进制文件要么包含所有需要的目标，要么设置以动态链接库 <code>*.so</code> 文件加载。</li></ol><p>你可以试试这个简单示例（可能需要对库路径做一些调整）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat &lt;&lt; EOF &gt;&gt; hello.c</span></span>
<span class="line"><span> #include</span></span>
<span class="line"><span> int main(void)</span></span>
<span class="line"><span> { printf(&quot;hello world\\n&quot;);</span></span>
<span class="line"><span>   return 0; }</span></span>
<span class="line"><span>   EOF</span></span>
<span class="line"><span>$ cpp hello.c &gt; hello.i</span></span>
<span class="line"><span>$ gcc -S hello.i</span></span>
<span class="line"><span>$ as -o hello.o hello.s</span></span>
<span class="line"><span>$ ld -static -o hello \\</span></span>
<span class="line"><span>  -L/usr/lib64/gcc/x86_64-slackware-linux/5.5.0/ \\</span></span>
<span class="line"><span>  /usr/lib64/crt1.o /usr/lib64/crti.o hello.o \\</span></span>
<span class="line"><span>  /usr/lib64/crtn.o  --start-group -lc -lgcc \\</span></span>
<span class="line"><span>  -lgcc_eh --end-group</span></span>
<span class="line"><span>$ ./hello</span></span>
<span class="line"><span>hello world</span></span></code></pre></div><h3 id="可获得的知识" tabindex="-1">可获得的知识 <a class="header-anchor" href="#可获得的知识" aria-label="Permalink to 可获得的知识">​</a></h3><p>计算机已经变得非常强大，并且用户友好。请不要走向这两种可能的极端中的任何一种：计算机不像捕鼠器和电灯开关那么简单，但它们也不是无法理解的。你可以了解编译代码、如何链接以及针对不同架构进行编译。一旦你知道了，你就可以更好地调试代码。你可以理解你下载的代码，甚至可以修复其中的一两个错误。同时从理论上来讲，你可以建造一个更好的捕鼠器，或者用捕鼠器造一个 CPU。由你决定。</p><hr>`,10)),a("p",null,[n[15]||(n[15]=s("via: ")),l(e,{href:"https://opensource.com/article/22/10/compiling-code"},{default:p(()=>n[14]||(n[14]=[s("https://opensource.com/article/22/10/compiling-code")])),_:1})]),a("p",null,[n[20]||(n[20]=s("作者：")),l(e,{href:"https://opensource.com/users/alansmithee"},{default:p(()=>n[16]||(n[16]=[s("Alan Smithee")])),_:1}),n[21]||(n[21]=s(" 选题：")),l(e,{href:"https://github.com/lkxed"},{default:p(()=>n[17]||(n[17]=[s("lkxed")])),_:1}),n[22]||(n[22]=s(" 译者：")),l(e,{href:"https://github.com/Donkey-Hao"},{default:p(()=>n[18]||(n[18]=[s("Donkey-Hao")])),_:1}),n[23]||(n[23]=s(" 校对：")),l(e,{href:"https://github.com/wxy"},{default:p(()=>n[19]||(n[19]=[s("wxy")])),_:1})]),a("p",null,[n[26]||(n[26]=s("本文由 ")),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>n[24]||(n[24]=[s("LCTT")])),_:1}),n[27]||(n[27]=s(" 原创编译，")),l(e,{href:"https://linux.cn/"},{default:p(()=>n[25]||(n[25]=[s("Linux中国")])),_:1}),n[28]||(n[28]=s(" 荣誉推出"))])])}const x=t(u,[["render",m]]);export{k as __pageData,x as default};
